<?php
require_once __DIR__.'/config.php'; require_once __DIR__.'/includes/policy-system.php'; requireLogin();
$db=db(); hrPolicyEnsureSchema($db); $u=currentUser();
$s=$db->prepare("SELECT a.*,v.version_number,v.created_date,v.effective_date,v.published_at,v.title,e.emp_number FROM hr_policy_acknowledgements a JOIN hr_policy_versions v ON v.id=a.version_id JOIN employees e ON e.id=a.employee_id WHERE a.id=?");
$s->execute(array((int)($_GET['id']??0))); $a=$s->fetch(PDO::FETCH_ASSOC);
if(!$a||empty($a['signed_at'])||($u['role']==='employee'&&(int)$a['employee_id']!==hrPolicyEmployeeId($u))){http_response_code(403);exit('Receipt not available.');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Policy acknowledgement receipt</title><link rel="stylesheet" href="includes/policies.css"></head><body class="receipt-body"><main class="receipt"><div class="receipt-actions"><a href="policies.php">← Policies</a><button onclick="print()">Print receipt</button></div><p class="eyebrow">Hambelela Organic</p><h1>Policy Acknowledgement Receipt</h1><dl>
<dt>Employee</dt><dd><?=htmlspecialchars($a['legal_name'])?></dd><dt>Employee ID</dt><dd><?=htmlspecialchars($a['emp_number']?:$a['employee_id'])?></dd><dt>Policy</dt><dd><?=htmlspecialchars($a['title'])?></dd><dt>Version</dt><dd><?=htmlspecialchars($a['version_number'])?></dd><dt>Document Hash</dt><dd class="hash"><?=htmlspecialchars($a['document_hash'])?></dd><dt>Created</dt><dd><?=date('j F Y',strtotime($a['created_date']))?></dd><dt>Published</dt><dd><?=date('j F Y H:i',strtotime($a['published_at']))?></dd><dt>Effective</dt><dd><?=date('j F Y',strtotime($a['effective_date']))?></dd><dt>Opened</dt><dd><?=date('j F Y H:i',strtotime($a['opened_at']))?></dd><dt>Signed</dt><dd><?=date('j F Y H:i',strtotime($a['signed_at']))?></dd><dt>Signature Method</dt><dd><?=htmlspecialchars(ucfirst($a['signature_method']))?></dd><dt>Acknowledgement Reference</dt><dd><?=htmlspecialchars($a['acknowledgement_reference'])?></dd></dl><section class="ack-copy"><?=nl2br(htmlspecialchars($a['acknowledgement_text']))?></section><?php if($a['signature_method']==='drawn'):?><section><h2>Digital signature</h2><img class="receipt-signature" src="<?=htmlspecialchars($a['signature_data'])?>" alt="Employee digital signature"></section><?php endif;?></main></body></html>
